package com.gameaggregator.gameservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="games") public class Game{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID studioId;public UUID publisherId;@Column(nullable=false,unique=true)public String slug;@Column(nullable=false)public String title;@Lob public String metadata="{}";@Column(nullable=false)public String visibility="PRIVATE";@Column(nullable=false)public String status="DRAFT";public String ageRating;@Column(nullable=false)public Instant createdAt=Instant.now();protected Game(){}public Game(UUID s,UUID p,String l,String t,String m,String v,String a){studioId=s;publisherId=p;slug=l;title=t;metadata=m;visibility=v;ageRating=a;}}